        ApiResponse<ResponseItemList> PostV2CardsMoveNmWithHttpInfo(PostV2CardsMoveNmRequest? postV2CardsMoveNmRequest = default(PostV2CardsMoveNmRequest?), int operationIndex = 0);
        /// <summary>
        /// Восстановление карточек товаров из корзины
